def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for v in row:
            counts[v] = counts.get(v, 0) + 1
    bg = max(counts, key=counts.get)
    mark = min(v for v in counts if v != bg)
    out = [row[:] for row in grid]
    # Fill only background cells strictly between consecutive occurrences of the
    # foreground marker, along rows and columns.
    for r in range(h):
        cols = [c for c in range(w) if grid[r][c] == mark]
        for a, b in zip(cols, cols[1:]):
            for c in range(a + 1, b):
